@SpringBootTest @AutoConfigureMockMvc @TestInstance(TestInstance.Lifecycle.PER_CLASS)
class ControlsTest {
 static final Path DATABASE;static {try{DATABASE=Files.createTempDirectory("eot-stage5-tests-").resolve("test.db");}catch(Exception e){throw new RuntimeException(e);}}
 static final String TOKEN="stage5-isolated-test-token-0123456789abcdef";
 @DynamicPropertySource static void props(DynamicPropertyRegistry r){r.add("spring.datasource.url",()->"jdbc:sqlite:"+DATABASE);r.add("eot.api-token",()->TOKEN);}
 @Autowired CatalogRepository repo;@Autowired BillingService billing;@Autowired CatalogService catalog;@Autowired StockService stock;@Autowired AuthService auth;
 @Autowired ReversalService reversals;@Autowired ExpenseService expenses;@Autowired BackupService backups;@Autowired ReportService reports;@Autowired CustomerService customers;@Autowired MockMvc mvc;@Autowired ObjectMapper json;
 AuthService.User owner;String session,cashierSession;
 @BeforeAll void setup(){owner=auth.setup("test-owner","test-only-owner-password");auth.create("test-biller","test-only-biller-password","BILLING");session=auth.login(owner.username(),"test-only-owner-password").get("session").toString();cashierSession=auth.login("test-biller","test-only-biller-password").get("session").toString();}
 @BeforeEach void clean(){for(String table:List.of("refunds","return_items","returns","expenses","checkout_requests","customer_changes","invoice_items","payments","stock_movements","invoices","customers","variant_taxes","product_variants","products"))repo.jdbc().update("DELETE FROM "+table);repo.jdbc().update("DELETE FROM application_settings WHERE key LIKE 'backup_%'");}
 String variant(String price,String cost,int qty){return catalog.save(null,new CatalogService.VariantInput(null,"TEST ONLY Stage5 shirt","shirts","TEST-"+UUID.randomUUID(),"M","Blue",null,cost==null?null:new BigDecimal(cost),new BigDecimal(price),qty,1,true,0),owner.id());}
 Map<String,Object> sale(String variant,int qty,long lineDiscount,long billDiscount,String customer){var cart=new BillingService.Cart(List.of(new BillingService.Line(variant,qty,lineDiscount)),billDiscount,customer);var q=billing.quote(cart,owner);return (Map<String,Object>)billing.checkout(new BillingService.Checkout(UUID.randomUUID(),cart,q.token(),q.totalPaise()==0?List.of():List.of(new BillingService.Payment(BillingService.Method.CASH,q.totalPaise()))),owner);}
 Map<String,Object> inv(Map<String,Object> sale){return (Map<String,Object>)sale.get("invoice");} Map<String,Object> item(Map<String,Object> sale){return ((List<Map<String,Object>>)sale.get("items")).getFirst();}
 ReversalService.Input input(Map<String,Object> sale,int qty,boolean restock,String kind){return new ReversalService.Input(UUID.randomUUID(),inv(sale).get("id").toString(),kind,"TEST ONLY reversal",List.of(new ReversalService.Line(item(sale).get("id").toString(),qty,restock)),List.of());}
 ReversalService.Input paid(ReversalService.Input input){long amount=((Number)reversals.preview(input).get("totalPaise")).longValue();return new ReversalService.Input(input.requestKey(),input.invoiceId(),input.kind(),input.reason(),input.lines(),amount==0?List.of():List.of(new BillingService.Payment(BillingService.Method.CASH,amount)));}
 ReportService.Range range(){return ReportService.range("month",null,null,LocalDate.now(ReportService.ZONE));}
 @Test void percentageAndFixedDiscountsReconcileAndPersistIntent(){
  String v=variant("10.01","3",5);billing.tax(new BillingService.Tax(v,500),owner.id());
  var cart=new BillingService.Cart(List.of(new BillingService.Line(v,3,0,"PERCENT",1250)),0,null,"PERCENT",1000);var q=billing.quote(cart,owner);
  assertEquals(375,q.items().getFirst().discountPaise());assertEquals(263,q.billDiscountPaise());assertEquals(118,q.taxPaise());assertEquals(2483,q.totalPaise());
  var result=(Map<?,?>)billing.checkout(new BillingService.Checkout(UUID.randomUUID(),cart,q.token(),List.of(new BillingService.Payment(BillingService.Method.CASH,2483))),owner);
  assertTrue(((Map<?,?>)result.get("invoice")).get("discount_input_json").toString().contains("PERCENT"));assertEquals(2,stock.stock(v));
  assertThrows(Exception.class,()->billing.quote(new BillingService.Cart(List.of(new BillingService.Line(v,1,1,"PERCENT",500)),0,null),owner));
  assertThrows(Exception.class,()->billing.quote(new BillingService.Cart(List.of(new BillingService.Line(v,1,0,"PERCENT",10001)),0,null),owner));
 }
 @Test void tinyRepeatedReturnsSumExactlyAndKeepOriginalInvoice(){String v=variant("0.01","0",3);var sale=sale(v,3,2,1,null);var before=new LinkedHashMap<>(inv(sale));for(int i=0;i<3;i++){var r=paid(input(sale,1,true,"RETURN"));reversals.commit(r,owner.id());reversals.commit(r,owner.id());}assertEquals(3,stock.stock(v));assertEquals(3,repo.jdbc().queryForObject("SELECT COUNT(*) FROM returns",Integer.class));assertEquals(0,repo.jdbc().queryForObject("SELECT SUM(total_paise) FROM returns",Long.class));assertEquals(before,inv(billing.invoice(before.get("id").toString())));assertThrows(Exception.class,()->reversals.preview(input(sale,1,true,"RETURN")));}
 @Test void partialReturnsRefundDiscountAndTaxToFinalPaise(){String v=variant("10.01","4",3);billing.tax(new BillingService.Tax(v,500),owner.id());var sale=sale(v,3,101,79,null);long original=ReportService.n(inv(sale),"total_paise");for(int i=0;i<3;i++)reversals.commit(paid(input(sale,1,true,"RETURN")),owner.id());assertEquals(original,repo.jdbc().queryForObject("SELECT SUM(total_paise) FROM returns",Long.class));assertEquals(original,repo.jdbc().queryForObject("SELECT SUM(amount_paise) FROM refunds",Long.class));assertEquals(3,stock.stock(v));assertEquals(0,ReportService.sum(reports.report("monthly",range(),null).rows(),"total_paise"));}
 @Test void simultaneousDuplicateReturnCommitsOnlyOnce()throws Exception{String v=variant("100","40",2);var sale=sale(v,2,0,0,null);var r=paid(input(sale,1,true,"RETURN"));try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->reversals.commit(r,owner.id()));var b=pool.submit(()->reversals.commit(r,owner.id()));a.get(20,TimeUnit.SECONDS);b.get(20,TimeUnit.SECONDS);}assertEquals(1,stock.stock(v));assertEquals(1,repo.jdbc().queryForObject("SELECT COUNT(*) FROM returns",Integer.class));}
 @Test void cancellationRequiresFullUntouchedInvoiceAndPreservesSale(){String v=variant("100","40",3);var sale=sale(v,2,0,0,null);assertThrows(Exception.class,()->reversals.preview(input(sale,1,true,"CANCELLATION")));var r=paid(input(sale,2,true,"CANCELLATION"));reversals.commit(r,owner.id());assertEquals(3,stock.stock(v));assertEquals("COMPLETED",inv(billing.invoice(inv(sale).get("id").toString())).get("status"));assertThrows(Exception.class,()->reversals.preview(input(sale,1,true,"RETURN")));}
 @Test void failureDuringRefundRollsBackReturnAndStock(){String v=variant("20","5",2);var sale=sale(v,1,0,0,null);var r=paid(input(sale,1,true,"RETURN"));repo.jdbc().execute("CREATE TRIGGER test_refund_failure BEFORE INSERT ON refunds BEGIN SELECT RAISE(ABORT,'TEST failure'); END");try{assertThrows(RuntimeException.class,()->reversals.commit(r,owner.id()));}finally{repo.jdbc().execute("DROP TRIGGER test_refund_failure");}assertEquals(1,stock.stock(v));assertEquals(0,repo.jdbc().queryForObject("SELECT COUNT(*) FROM returns",Integer.class));assertEquals(0,repo.jdbc().queryForObject("SELECT COUNT(*) FROM return_items",Integer.class));}
 @Test void refundMismatchAndChangedIdempotencyKeyCannotMutateStock(){String v=variant("100","40",2);var sale=sale(v,1,0,0,null);var r=input(sale,1,true,"RETURN");assertThrows(Exception.class,()->reversals.commit(r,owner.id()));assertEquals(1,stock.stock(v));var paid=paid(r);reversals.commit(paid,owner.id());var changed=new ReversalService.Input(paid.requestKey(),paid.invoiceId(),paid.kind(),"Different reason",paid.lines(),paid.refunds());assertThrows(Exception.class,()->reversals.commit(changed,owner.id()));assertEquals(2,stock.stock(v));}
 @Test void profitLossExpensesAndNonRestockReturnsReconcile(){String v=variant("100","40",3);var sale=sale(v,2,0,0,null);reversals.commit(paid(input(sale,1,false,"RETURN")),owner.id());expenses.create(new ExpenseService.Input(UUID.randomUUID(),"rent",3000,LocalDate.now(ReportService.ZONE),BillingService.Method.CASH,"TEST ONLY rent"),owner.id());var row=reports.report("net-profit",range(),null).rows().getFirst();assertEquals(10000,ReportService.n(row,"net_sales_paise"));assertEquals(8000,ReportService.n(row,"cost_paise"));assertEquals(-1000,ReportService.n(row,"net_profit_paise"));assertEquals(1,stock.stock(v));assertEquals(10000,ReportService.sum(reports.report("payments",range(),null).rows(),"collections_paise"));}
 @Test void missingCostsDoNotPretendToBeFullProfitAndVoidsAreRetained(){String v=variant("100",null,2);sale(v,1,0,0,null);var e=new ExpenseService.Input(UUID.randomUUID(),"other",3000,LocalDate.now(ReportService.ZONE),BillingService.Method.UPI,"TEST ONLY expense");var saved=(Map<?,?>)expenses.create(e,owner.id());expenses.create(e,owner.id());assertEquals(1,repo.jdbc().queryForObject("SELECT COUNT(*) FROM expenses",Integer.class));var row=reports.report("net-profit",range(),null).rows().getFirst();assertNull(row.get("net_profit_paise"));assertEquals(1,ReportService.n(row,"unknown_cost_units"));expenses.voidExpense(saved.get("id").toString(),"TEST ONLY correction",owner.id());assertEquals(0,ReportService.n(reports.report("net-profit",range(),null).rows().getFirst(),"expenses_paise"));assertNotNull(repo.jdbc().queryForObject("SELECT voided_at FROM expenses",String.class));}
 @Test void customerLifetimeTotalsSubtractRefundsButPreserveHistory(){String c=((Map<?,?>)billing.customer(new BillingService.CustomerInput("TEST ONLY Customer","9999900055",null),owner.id())).get("id").toString();var sale=sale(variant("100","40",2),2,0,0,c);reversals.commit(paid(input(sale,1,true,"RETURN")),owner.id());var result=(Map<?,?>)customers.detail(c,0);assertEquals(10000,ReportService.n((Map<String,Object>)result.get("summary"),"amount_paise"));assertEquals(1,((List<?>)result.get("invoices")).size());assertEquals(10000,ReportService.sum(reports.report("customers",range(),null).rows(),"total_paise"));}
 @Test void backupRestoreRetainsWALRecordsAndRescueAndExportIds()throws Exception{
  var sale=sale(variant("100","40",3),1,0,0,null);Path folder=Files.createTempDirectory("eot-backup-test-");backups.configure(new BackupService.Config(folder.toString(),0,2),owner.id());var backup=(Map<?,?>)backups.backup(owner.id());Path file=Path.of(backup.get("path").toString());assertEquals("ok",BackupFiles.validate(file).get("health"));
  var exported=json.readTree(backups.exportDatabase());assertEquals(inv(sale).get("id"),exported.path("tables").path("invoices").get(0).path("id").asText());
  Path restoreDir=Files.createTempDirectory("eot-restore-test-");Path live=restoreDir.resolve("eastoftown.db"),staged=restoreDir.resolve("pending-restore.db");BackupFiles.snapshot(DATABASE,live);BackupFiles.snapshot(file,staged);
  try(var connection=DriverManager.getConnection("jdbc:sqlite:"+live);var s=connection.createStatement()){s.execute("PRAGMA journal_mode=WAL");s.execute("INSERT INTO application_settings VALUES ('test-newer-record','preserve-in-rescue')");}
  String rescue="rescue-"+UUID.randomUUID()+".db";Files.writeString(restoreDir.resolve("restore-request.txt"),BackupFiles.hash(Files.readAllBytes(staged))+"\n"+rescue+"\n");BackupFiles.restorePending(restoreDir);assertTrue(Files.exists(restoreDir.resolve(rescue)));assertFalse(Files.exists(restoreDir.resolve("restore-request.txt")));assertEquals(1L,((Map<?,?>)BackupFiles.validate(live).get("counts")).get("invoices"));
  try(var c=BackupFiles.read(restoreDir.resolve(rescue));var s=c.createStatement();var r=s.executeQuery("SELECT value FROM application_settings WHERE key='test-newer-record'")){assertTrue(r.next());assertEquals("preserve-in-rescue",r.getString(1));}
 }
 @Test void corruptAndTamperedBackupsCannotReplaceLiveOrOverwriteGoodCopies()throws Exception{
  Path directory=Files.createTempDirectory("eot-corrupt-test-");Path bad=directory.resolve("bad.db");Files.writeString(bad,"not a database");assertThrows(Exception.class,()->BackupFiles.validate(bad));Path good=directory.resolve("good.db");BackupFiles.snapshot(DATABASE,good);String hash=BackupFiles.hash(Files.readAllBytes(good));assertThrows(Exception.class,()->BackupFiles.snapshot(DATABASE,good));assertEquals(hash,BackupFiles.hash(Files.readAllBytes(good)));
  Path live=directory.resolve("eastoftown.db"),staged=directory.resolve("pending-restore.db");BackupFiles.snapshot(DATABASE,live);Files.copy(bad,staged);String before=BackupFiles.hash(Files.readAllBytes(live));Files.writeString(directory.resolve("restore-request.txt"),"wrong-checksum\nrescue-"+UUID.randomUUID()+".db\n");assertThrows(Exception.class,()->BackupFiles.restorePending(directory));assertEquals(before,BackupFiles.hash(Files.readAllBytes(live)));
 }
 @Test void backupRetentionAndFailedDestinationKeepGoodCopy()throws Exception{Path directory=Files.createTempDirectory("eot-retention-test-");backups.configure(new BackupService.Config(directory.toString(),0,2),owner.id());for(int i=0;i<3;i++)backups.backup(owner.id());try(var paths=Files.list(directory)){assertEquals(2,paths.filter(p->p.toString().endsWith(".db")).count());}Path bad=directory.resolve("file-not-folder");Files.writeString(bad,"TEST ONLY");backups.configure(new BackupService.Config(bad.toString(),0,2),owner.id());assertThrows(Exception.class,()->backups.backup(owner.id()));try(var paths=Files.list(directory)){assertEquals(2,paths.filter(p->p.toString().endsWith(".db")).count());}}
 @Test void adminPasswordResetRevokesSessionsAndRestrictedActionsDenyBilling()throws Exception{
  var user=auth.create("reset-"+UUID.randomUUID().toString().substring(0,8),"test-only-original-password","BILLING");String oldSession=auth.login(user.username(),"test-only-original-password").get("session").toString();
  mvc.perform(post("/api/auth/users/"+user.id()+"/reset").header("X-EOT-Token",TOKEN).header("X-EOT-Session",session).contentType(MediaType.APPLICATION_JSON).content("{\"password\":\"test-only-new-password\"}")).andExpect(status().isOk());
  mvc.perform(get("/api/billing/settings").header("X-EOT-Token",TOKEN).header("X-EOT-Session",oldSession)).andExpect(status().isUnauthorized());assertThrows(Exception.class,()->auth.login(user.username(),"test-only-original-password"));assertNotNull(auth.login(user.username(),"test-only-new-password"));
  for(String route:List.of("/api/backups","/api/auth/users","/api/controls/expenses","/api/reports/net-profit"))mvc.perform(get(route).header("X-EOT-Token",TOKEN).header("X-EOT-Session",cashierSession)).andExpect(status().isForbidden());
  mvc.perform(post("/api/auth/users/"+owner.id()+"/state").header("X-EOT-Token",TOKEN).header("X-EOT-Session",session).contentType(MediaType.APPLICATION_JSON).content("{\"role\":\"BILLING\",\"active\":false}")).andExpect(status().isBadRequest());
 }
 @Test void sharingValidatesRecipientAndPngMatchesReceiptLayout()throws Exception{var sale=sale(variant("100","40",2),1,0,0,null);String id=inv(sale).get("id").toString();mvc.perform(post("/api/billing/invoices/"+id+"/share").header("X-EOT-Token",TOKEN).header("X-EOT-Session",session).contentType(MediaType.APPLICATION_JSON).content("{\"phone\":\"not-a-number\"}")).andExpect(status().isBadRequest());var png=mvc.perform(get("/api/billing/invoices/"+id+"/png").header("X-EOT-Token",TOKEN).header("X-EOT-Session",session)).andExpect(status().isOk()).andReturn().getResponse().getContentAsByteArray();assertEquals(0x89,png[0]&255);assertTrue(png.length>1000);}
 @Test void scheduleRunsOnceWhenDueAndDoesNotReplacePreviousGoodCopies()throws Exception{Path folder=Files.createTempDirectory("eot-scheduled-test-");backups.configure(new BackupService.Config(folder.toString(),1,3),owner.id());backups.scheduled();assertFalse(backups.setting("backup_last_success").isEmpty());backups.scheduled();try(var files=Files.list(folder)){assertEquals(1,files.filter(f->f.toString().endsWith(".db")).count());}}
 @Test void backupManifestTamperingIsRejectedBeforeRestore()throws Exception{Path folder=Files.createTempDirectory("eot-hash-test-");backups.configure(new BackupService.Config(folder.toString(),0,2),owner.id());var saved=(Map<?,?>)backups.backup(owner.id());Path source=Path.of(saved.get("path").toString());Files.writeString(Path.of(source+".json"),"{\"sha256\":\"tampered\"}");assertThrows(Exception.class,()->backups.stageRestore(source.toString(),owner.id()));assertFalse(backups.restorePending());}
 @Test void restrictedWriteEndpointsRejectBillingUser()throws Exception{
  var expense=new ExpenseService.Input(UUID.randomUUID(),"rent",100,LocalDate.now(ReportService.ZONE),BillingService.Method.CASH,"TEST ONLY denied");
  var reversal=new ReversalService.Input(UUID.randomUUID(),UUID.randomUUID().toString(),"RETURN","TEST ONLY denied",List.of(new ReversalService.Line(UUID.randomUUID().toString(),1,true)),List.of());
  for(var test:List.of(Map.entry("/api/controls/expenses",json.writeValueAsString(expense)),Map.entry("/api/controls/returns",json.writeValueAsString(reversal)),Map.entry("/api/backups","{}"),Map.entry("/api/backups/restore","{\"path\":\"test.db\"}"),Map.entry("/api/auth/users/"+owner.id()+"/reset","{\"password\":\"test-only-new-password\"}")))mvc.perform(post(test.getKey()).header("X-EOT-Token",TOKEN).header("X-EOT-Session",cashierSession).contentType(MediaType.APPLICATION_JSON).content(test.getValue())).andExpect(status().isForbidden());
 }
}
